function qs(obj, prefix) {
  return Object.entries(obj).filter(([, v]) => v !== undefined && v !== null).map(([k, v]) => {
    const key = prefix ? `${prefix}[${k}]` : k;
    if (v && typeof v === 'object' && !('raw' in v)) return qs(v, key);
    const val = (v && typeof v === 'object') ? v.raw : encodeURIComponent(String(v));
    return `${key}=${val}`;
  }).filter(Boolean).join('&');
}

const s = $('Route').first().json.state;
const cfg = s.cfg, n = s.norm, rt = s.route;
const prefix = cfg.crm_title_prefix ?? '';
const mgr = rt.manager_id;

let repair = null;
if (s.crm.deal) {
  const rr = $('b24: repair lookup').first().json;
  if (!rr.ok) throw new Error(`Bitrix24 repair lookup failed: ${rr.error_code}`);
  const x = rr.result?.result ?? {};
  repair = {
    task_id: Number(x.tasks?.tasks?.[0]?.id) || null,
    sla_item_id: Number(x.sla?.items?.[0]?.id) || null,
    comment_exists: (Array.isArray(x.comments) ? x.comments : []).some((c) => String(c.COMMENT ?? '').includes('[b24hub]')),
  };
}

const minutes = Number(n.score.urgency === 'high' ? cfg.sla_minutes_high : cfg.sla_minutes_normal);
const dueMs = Date.now() + minutes * 60000;
const msk = (ms) => new Date(ms + 3 * 3600e3).toISOString().slice(0, 19) + '+03:00';
const hhmm = new Date(dueMs + 3 * 3600e3).toISOString().slice(11, 16);
const ddmm = new Date(dueMs + 3 * 3600e3).toISOString().slice(5, 10).split('-').reverse().join('.');
const who = s.dadata?.name ?? n.company.name ?? n.contact.name ?? n.contact.phone ?? n.contact.email;
const SOURCE = { web: 'WEB', telegram: 'TELEGRAM', email: 'EMAIL', api: 'OTHER' };

const deal = s.crm.deal ? Number(s.crm.deal.ID) : null;
const dealRef = deal ?? { raw: '$result[deal]' };
const cmd = {};
let companyRef = s.crm.company_id;
if (!deal) {
  if (n.company.inn_valid && !s.crm.company_id) {
    cmd.company = 'crm.company.add?' + qs({ fields: {
      TITLE: prefix + (s.dadata?.name ?? n.company.name ?? `ИНН ${n.company.inn}`), ASSIGNED_BY_ID: mgr,
      ORIGINATOR_ID: 'b24hub', ORIGIN_ID: n.company.inn, OPENED: 'Y' } });
    const ip = n.company.inn.length === 12;
    cmd.requisite = 'crm.requisite.add?' + qs({ fields: {
      ENTITY_TYPE_ID: 4, ENTITY_ID: { raw: '$result[company]' },
      PRESET_ID: ip ? cfg.requisite_preset_ip : cfg.requisite_preset_org,
      NAME: s.dadata?.name ?? n.company.name ?? n.company.inn, RQ_INN: n.company.inn,
      RQ_KPP: ip ? undefined : s.dadata?.kpp ?? undefined,
      [ip ? 'RQ_OGRNIP' : 'RQ_OGRN']: s.dadata?.ogrn ?? undefined } });
    companyRef = { raw: '$result[company]' };
  }
  if (!s.crm.contact_id) {
    const f = { NAME: prefix + (n.contact.first ?? n.contact.phone ?? n.contact.email), LAST_NAME: n.contact.last ?? undefined,
                ASSIGNED_BY_ID: mgr, SOURCE_ID: SOURCE[n.source] ?? 'OTHER', ORIGINATOR_ID: 'b24hub',
                ORIGIN_ID: n.contact.phone ?? n.contact.email, COMPANY_ID: companyRef ?? undefined, OPENED: 'Y' };
    if (n.contact.phone) f.PHONE = [{ VALUE: n.contact.phone, VALUE_TYPE: 'WORK' }];
    if (n.contact.email) f.EMAIL = [{ VALUE: n.contact.email, VALUE_TYPE: 'WORK' }];
    cmd.contact = 'crm.contact.add?' + qs({ fields: f });
  }
  const utm = n.utm ?? {};
  cmd.deal = 'crm.deal.add?' + qs({ fields: {
    TITLE: `${prefix}${n.score.topic !== 'other' ? n.score.topic : (n.product ?? 'заявка')} — ${who}`,
    CONTACT_ID: s.crm.contact_id ?? { raw: '$result[contact]' }, COMPANY_ID: companyRef ?? undefined,
    ASSIGNED_BY_ID: mgr, SOURCE_ID: SOURCE[n.source] ?? 'OTHER', SOURCE_DESCRIPTION: `b24hub inbox #${s.inbox_id}`,
    COMMENTS: n.message ?? undefined, OPPORTUNITY: n.score.budget ?? undefined, CURRENCY_ID: n.score.budget ? 'RUB' : undefined,
    ORIGINATOR_ID: 'b24hub', ORIGIN_ID: s.idempotency_key, OPENED: 'Y',
    UTM_SOURCE: utm.source, UTM_MEDIUM: utm.medium, UTM_CAMPAIGN: utm.campaign } });
}
if (!repair?.task_id) {
  cmd.task = 'tasks.task.add?' + qs({ fields: {
    TITLE: `${prefix}Ответить клиенту: ${who}`, RESPONSIBLE_ID: mgr, DEADLINE: msk(dueMs),
    UF_CRM_TASK: [deal ? `D_${deal}` : { raw: 'D_$result[deal]' }],
    DESCRIPTION: `Первый ответ до ${hhmm} (${minutes} мин, срочность: ${n.score.urgency}).\n${n.message ?? ''}` } });
}
if (!repair?.sla_item_id) {
  cmd.sla = 'crm.item.add?' + qs({ entityTypeId: cfg.sla_entity_type_id, fields: {
    title: `${prefix}SLA до ${hhmm} ${ddmm} — ${who}`, assignedById: mgr, parentId2: dealRef,
    stageId: cfg.sla_stage_waiting, begindate: msk(Date.now()), closedate: msk(dueMs),
    observers: cfg.rop_user_id ? [cfg.rop_user_id] : undefined,
    ...(cfg.sla_due_field ? { [cfg.sla_due_field]: msk(dueMs) } : {}) } });
}
const ev = Object.fromEntries(s.events.map((e) => [e.step, e.detail]));
const lines = [
  `[B]b24hub[/B] обработал заявку #${s.inbox_id} (${n.source}) [b24hub]`,
  `Назначен: ${mgr} — ${rt.reason}`,
  ev.dedup?.contact_id ? `Контакт найден (${ev.dedup.matched_by}): #${ev.dedup.contact_id}` : 'Контакт: новый',
  ev.enrich?.name ? `DaData: ${ev.enrich.name}${ev.enrich.status ? `, статус ${ev.enrich.status}` : ''}` : (n.company.inn_raw ? `ИНН ${n.company.inn_raw}: ${n.company.inn_valid ? 'не найден в DaData' : 'контрольная сумма не сошлась'}` : 'ИНН: не указан'),
  `Оценка (${n.score.method}): тема ${n.score.topic}, срочность ${n.score.urgency}${n.score.budget ? `, бюджет ${n.score.budget} ₽` : ''}`,
  `SLA первого ответа: ${minutes} мин, до ${hhmm} ${ddmm}`,
  ...(n.warnings.length ? [`Нормализация: ${n.warnings.join('; ')}`] : []),
];
if (!repair?.comment_exists) {
  cmd.comment = 'crm.timeline.comment.add?' + qs({ fields: { ENTITY_ID: dealRef, ENTITY_TYPE: 'deal', COMMENT: lines.join('\n') } });
}
if (!Object.keys(cmd).length) cmd.check = `crm.deal.get?id=${deal}`;
return [{ json: { method: 'batch', params: { halt: 1, cmd }, caller_workflow: $workflow.name, caller_execution_id: $execution.id,
                  state: { ...s, repair, sla_due: new Date(dueMs).toISOString(), sla_minutes: minutes, planned: Object.keys(cmd) } } }];

const s = $('Prepare lookup').first().json.state;
const r = $json;
if (!r.ok) throw new Error(`Bitrix24 lookup failed: ${r.error_code} ${r.error_description ?? ''}`);
const res = r.result?.result ?? {};
const ids = (x) => (Array.isArray(x?.CONTACT) ? x.CONTACT : []).map(Number);
const byPhone = ids(res.phone), byEmail = ids(res.email);
const all = [...new Set([...byPhone, ...byEmail])].sort((a, b) => a - b);
const contactId = all[0] ?? null;  // oldest record wins
const owner = Number((byPhone.length ? res.owner_p : byEmail.length ? res.owner_e : null)?.ASSIGNED_BY_ID
                     ?? res.owner_c?.ASSIGNED_BY_ID ?? 0) || null;
const deal = Array.isArray(res.deal) && res.deal.length ? res.deal[0] : null;
// A deal left by a previous attempt keeps its assignee: routing must not move it.
const dealOwner = deal ? Number(deal.ASSIGNED_BY_ID) || null : null;
const companyId = Number(Array.isArray(res.company) && res.company[0]?.ENTITY_ID) || null;
const detail = {
  contact_id: contactId, matched_by: byPhone.length ? 'phone' : byEmail.length ? 'email' : null,
  company_id: companyId, owner_id: owner, existing_deal_id: deal ? Number(deal.ID) : null,
};
if (all.length > 1) detail.crm_duplicates = all;  // pre-existing duplicates in CRM: reported, not merged
// Region for routing: DaData (by INN) is more reliable than what the client typed.
const routeRegion = s.dadata?.region ? String(s.dadata.region).toLowerCase().replace(/ё/g, 'е') : s.norm.region_canonical;
return [{ json: { ...s, crm: { contact_id: contactId, company_id: companyId, owner_id: dealOwner ?? owner, deal: deal },
                  route_region: routeRegion,
                  events: [...s.events, { step: 'dedup', detail }] } }];

const s = $('Build create').first().json.state;
const r = $json;
if (!r.ok) throw new Error(`Bitrix24 create batch failed: ${r.error_code} ${r.error_description ?? ''}`);
const res = r.result?.result ?? {};
const errs = Object.entries(r.result?.result_error ?? {}).filter(([, v]) => v && !(Array.isArray(v) && !v.length));
if (errs.length) throw new Error(`Bitrix24 create failed at "${errs[0][0]}": ${JSON.stringify(errs[0][1]).slice(0, 400)}`);
const out = {
  deal_id: s.crm.deal ? Number(s.crm.deal.ID) : Number(res.deal),
  contact_id: s.crm.contact_id ?? (Number(res.contact) || null),
  company_id: s.crm.company_id ?? (Number(res.company) || null),
  task_id: s.repair?.task_id ?? (Number(res.task?.task?.id) || null),
  sla_item_id: s.repair?.sla_item_id ?? (Number(res.sla?.item?.id) || null),
  manager_id: s.route.manager_id,
  created: s.planned,
  repaired: !!s.crm.deal,
};
if (!out.deal_id || !out.sla_item_id || !out.task_id) throw new Error(`Bitrix24 create returned incomplete ids: ${JSON.stringify(out)}`);
const events = [...s.events, { step: 'route', detail: s.route }, { step: 'crm', detail: out }];
return [{ json: { inbox_id: s.inbox_id, execution_id: s.execution_id, sla_due: s.sla_due, result: { ...out, score: s.norm.score }, events } }];

// ---- pure functions: unit-tested by tests/test_normalize.py (runs this exact code under node) ----
const PHONE_EXT = /(доб\.?|ext\.?|extension|#).*$/i;

function normalizePhone(raw) {
  if (raw === undefined || raw === null || String(raw).trim() === '') return { value: null, error: null };
  const s = String(raw).trim().replace(PHONE_EXT, '').trim();
  const digits = s.replace(/\D/g, '');
  const plus = s.startsWith('+');
  let e164 = null;
  if (digits.length === 11 && (digits[0] === '7' || (digits[0] === '8' && !plus))) e164 = '+7' + digits.slice(1);
  else if (digits.length === 10 && !plus && /^[3489]/.test(digits)) e164 = '+7' + digits;
  else if (plus && digits[0] !== '7' && digits.length >= 8 && digits.length <= 15) e164 = '+' + digits;
  if (e164 && e164.startsWith('+7') && !/^\+7[3489]\d{9}$/.test(e164)) e164 = null;
  return e164 ? { value: e164, error: null } : { value: null, error: `phone "${String(raw).trim()}" is not a valid number` };
}

function normalizeEmail(raw) {
  if (raw === undefined || raw === null || String(raw).trim() === '') return { value: null, error: null };
  const s = String(raw).trim().replace(/^mailto:/i, '').toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@.]{2,}$/.test(s) && s.length <= 254
    ? { value: s, error: null } : { value: null, error: `email "${String(raw).trim()}" is not valid` };
}

function innValid(inn) {
  const s = String(inn ?? '').trim();
  if (!/^(\d{10}|\d{12})$/.test(s)) return false;
  const d = s.split('').map(Number);
  const chk = (w) => (w.reduce((acc, k, i) => acc + k * d[i], 0) % 11) % 10;
  if (s.length === 10) return chk([2, 4, 10, 3, 5, 9, 4, 6, 8]) === d[9];
  return chk([7, 2, 4, 10, 3, 5, 9, 4, 6, 8]) === d[10] && chk([3, 7, 2, 4, 10, 3, 5, 9, 4, 6, 8]) === d[11];
}

const REGION_STOP = new Set(['г', 'город', 'обл', 'область', 'край', 'респ', 'республика', 'ао', 'автономный', 'округ']);
const REGION_ALIAS = { 'спб': 'санкт-петербург', 'питер': 'санкт-петербург', 'санкт петербург': 'санкт-петербург', 'мск': 'москва' };
function canonicalRegion(raw) {
  if (!raw) return null;
  const words = String(raw).toLowerCase().replace(/ё/g, 'е').split(/[\s,.]+/).filter((w) => w && !REGION_STOP.has(w));
  const s = words.join(' ').trim();
  return s ? (REGION_ALIAS[s] ?? s) : null;
}

function splitName(raw) {
  const parts = String(raw ?? '').trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return { first: null, last: null };
  return { first: parts[0], last: parts.slice(1).join(' ') || null };
}

// Deterministic fallback scorer; an LLM scorer can replace it (stage 6 provides the keys).
function scoreLead(message, product) {
  const m = String(message ?? '');
  const urgency = /срочн|сегодня|немедленн|горит|asap|urgent|как можно скорее/i.test(m) ? 'high' : 'normal';
  let budget = null;
  const b = m.match(/(\d[\d\s]*(?:[.,]\d+)?)\s*(млн|миллион|тыс|т\.р|k|к|руб|₽)/i);
  if (b) {
    const n = parseFloat(b[1].replace(/\s/g, '').replace(',', '.'));
    const mult = /млн|миллион/i.test(b[2]) ? 1e6 : /тыс|т\.р|^k$|^к$/i.test(b[2]) ? 1e3 : 1;
    budget = Math.round(n * mult);
  }
  const topics = [['integration', /интеграц|api|1с|1c|синхрон/i], ['telephony', /телефон|звонк|ip-?атс/i], ['crm', /crm|црм|воронк|сделк/i]];
  const topic = (product ? String(product).toLowerCase() : null) ?? topics.find(([, rx]) => rx.test(m))?.[0] ?? 'other';
  return { method: 'rules', topic, urgency, budget };
}

function normalizeLead(p) {
  const warnings = [];
  const c = p.contact ?? {};
  const phone = normalizePhone(c.phone);
  const email = normalizeEmail(c.email);
  if (phone.error) warnings.push(phone.error);
  if (email.error) warnings.push(email.error);
  const inn = p.company?.inn !== undefined ? String(p.company.inn).trim() : null;
  const inn_valid = inn ? innValid(inn) : false;
  if (inn && !inn_valid) warnings.push(`INN ${inn}: checksum mismatch, company enrichment skipped`);
  const name = c.name ? String(c.name).trim() : null;
  return {
    source: p.source,
    contact: { name, ...splitName(name), phone: phone.value, email: email.value },
    company: { name: p.company?.name ?? null, inn: inn_valid ? inn : null, inn_raw: inn, inn_valid },
    region: p.region ?? null,
    region_canonical: canonicalRegion(p.region),
    product: p.product ? String(p.product).toLowerCase() : null,
    message: p.message ?? null,
    utm: p.utm ?? null,
    score: scoreLead(p.message, p.product),
    warnings,
    reject_reason: phone.value || email.value ? null : 'no valid phone or email after normalization',
  };
}

// ---- n8n entry ----
const s = $json.state;
const n = normalizeLead(s.payload);
const events = [{ step: 'normalize', detail: { phone: n.contact.phone, email: n.contact.email, inn_valid: n.company.inn_valid, warnings: n.warnings } },
                { step: 'score', detail: n.score }];
if (n.reject_reason) events.push({ step: 'rejected', detail: { reason: n.reject_reason } });
return [{ json: { ...s, norm: n, events } }];

// Enrichment is best-effort: an HTTP error from DaData is recorded and the lead continues.
const s = $('DaData cache').first().json.state;
const status = Number($json.statusCode ?? 0);
const sug = status === 200 ? ($json.body?.suggestions ?? [])[0] : null;
const d = sug?.data;
const data = d ? {
  name: sug.value, full_name: d.name?.full_with_opf ?? null, type: d.type ?? null,
  kpp: d.kpp ?? null, ogrn: d.ogrn ?? null, status: d.state?.status ?? null,
  region: d.address?.data?.region ?? null, region_with_type: d.address?.data?.region_with_type ?? null,
  address: d.address?.value ?? null, okved: d.okved ?? null,
} : null;
const events = [...s.events, { step: 'enrich', detail: status === 200
  ? (data ? { source: 'dadata', name: data.name, status: data.status, region: data.region_with_type } : { source: 'dadata', found: false })
  : { source: 'dadata', error: `HTTP ${status}` } }];
return [{ json: { state: { ...s, dadata: data, events }, store: status === 200, found: !!data } }];

function qs(obj, prefix) {
  return Object.entries(obj).filter(([, v]) => v !== undefined && v !== null).map(([k, v]) => {
    const key = prefix ? `${prefix}[${k}]` : k;
    if (v && typeof v === 'object' && !('raw' in v)) return qs(v, key);
    const val = (v && typeof v === 'object') ? v.raw : encodeURIComponent(String(v));
    return `${key}=${val}`;
  }).filter(Boolean).join('&');
}

// One batch call: duplicates by phone and by email (crm.duplicate.findbycomm), the owners of the
// matched contacts, the company by INN (requisites), and our own deal by ORIGIN_ID (idempotency
// on the CRM side: a retried lead must find the deal it already created).
let s = $json.state;
if (s.dadata_cached) s = { ...s, events: [...s.events, { step: 'enrich', detail: { source: 'cache', name: s.dadata?.name ?? null } }] };
const n = s.norm;
const cmd = {
  deal: 'crm.deal.list?' + qs({ filter: { ORIGINATOR_ID: 'b24hub', ORIGIN_ID: s.idempotency_key }, select: ['ID', 'ASSIGNED_BY_ID', 'CONTACT_ID', 'COMPANY_ID'] }),
};
if (n.contact.phone) {
  cmd.phone = 'crm.duplicate.findbycomm?' + qs({ type: 'PHONE', values: [n.contact.phone], entity_type: 'CONTACT' });
  cmd.owner_p = 'crm.contact.get?id=$result[phone][CONTACT][0]';
}
if (n.contact.email) {
  cmd.email = 'crm.duplicate.findbycomm?' + qs({ type: 'EMAIL', values: [n.contact.email], entity_type: 'CONTACT' });
  cmd.owner_e = 'crm.contact.get?id=$result[email][CONTACT][0]';
}
if (n.company.inn_valid) {
  cmd.company = 'crm.requisite.list?' + qs({ filter: { RQ_INN: n.company.inn, ENTITY_TYPE_ID: 4 }, select: ['ENTITY_ID'] });
  cmd.owner_c = 'crm.company.get?id=$result[company][0][ENTITY_ID]';
}
return [{ json: { method: 'batch', params: { halt: 0, cmd }, caller_workflow: $workflow.name, caller_execution_id: $execution.id, state: s } }];

function qs(obj, prefix) {
  return Object.entries(obj).filter(([, v]) => v !== undefined && v !== null).map(([k, v]) => {
    const key = prefix ? `${prefix}[${k}]` : k;
    if (v && typeof v === 'object' && !('raw' in v)) return qs(v, key);
    const val = (v && typeof v === 'object') ? v.raw : encodeURIComponent(String(v));
    return `${key}=${val}`;
  }).filter(Boolean).join('&');
}

// A previous attempt created the deal but may have failed before task / SLA item / comment.
const s = $json.state;
const dealId = Number(s.crm.deal.ID);
const cmd = {
  tasks: 'tasks.task.list?' + qs({ filter: { UF_CRM_TASK: 'D_' + dealId }, select: ['ID'] }),
  sla: 'crm.item.list?' + qs({ entityTypeId: s.cfg.sla_entity_type_id, filter: { parentId2: dealId }, select: ['id'] }),
  comments: 'crm.timeline.comment.list?' + qs({ filter: { ENTITY_ID: dealId, ENTITY_TYPE: 'deal' }, select: ['ID', 'COMMENT'] }),
};
return [{ json: { method: 'batch', params: { halt: 0, cmd }, caller_workflow: $workflow.name, caller_execution_id: $execution.id } }];
